package special

import (
	"math"

	"github.com/go-numerics/special/internal/dd"
)

// octPiece is one piece of a table generated by tools/genfit
// (octaves, ellip-oct): on it the function is coef[0] s^11 + ... +
// coef[11] with s = x - c, the constant term carrying c0lo as its low part.
// The tables cut every octave [2^e, 2^(e+1)) of the variable into 8 pieces
// of equal width.
type octPiece struct {
	c, c0lo float64
	coef    [12]float64
}

// octIndex returns the index of the piece holding x > 0 in a table whose
// first octave is 2^emin and last 2^emax, from the exponent and the top
// three mantissa bits of x, or -1 outside [2^emin, 2^(emax+1)).
func octIndex(x float64, emin, emax int) int {
	b := math.Float64bits(x)
	e := int(b>>52) - 1023
	if e < emin || e > emax {
		return -1
	}
	return (e-emin)<<3 | int(b>>49&7)
}

// octTail returns s q(s) + c0lo, the part of the piece beyond its constant
// term coef[11]: the value is coef[11] + octTail, which callers round once
// (or carry on as a double-double).
func octTail(q *octPiece, s float64) float64 {
	c := &q.coef
	r := c[0]
	r = r*s + c[1]
	r = r*s + c[2]
	r = r*s + c[3]
	r = r*s + c[4]
	r = r*s + c[5]
	r = r*s + c[6]
	r = r*s + c[7]
	r = r*s + c[8]
	r = r*s + c[9]
	r = r*s + c[10]
	return r*s + q.c0lo
}

// octEval evaluates a piece at s = x - c with one rounding: the tail is a
// small fraction of the constant term on every piece of every table (it is
// at most the variation of the function over half a piece).
func octEval(q *octPiece, s float64) float64 {
	return q.coef[11] + octTail(q, s)
}

// octExpMul returns e^t times the piece's value at s, rounded once: e^t =
// m 2^k from dd.ExpMant (about 2^-76 relative), the product formed with
// TwoProd. The caller keeps t in the range where m 2^k stays normal.
func octExpMul(q *octPiece, s, t float64) float64 {
	m, k := dd.ExpMant(dd.DD{Hi: t})
	c0 := q.coef[11]
	p, pe := dd.TwoProd(m.Hi, c0)
	r := p + (pe + m.Hi*octTail(q, s) + m.Lo*c0)
	return math.Ldexp(r, k)
}
